# ============================================================================
# CACHE UTILITIES CLASS
# ============================================================================
class CacheUtils:
    """
    Centralized cache management utilities.
    Handles CSV caching, freshness checks, regeneration, etc.
    """

    @staticmethod
    def check_and_generate_csv(
        file_name: str,
        generate_function: Callable,  # type: ignore[type-arg]
        freshness_minutes: int | None = None,
    ) -> bool:
        """
        Checks if a CSV file exists and is fresh (modified within the last `freshness_minutes`).
        If not, it runs the `generate_function` to regenerate the file.
        freshness_minutes is now settable via the .env file as CSV_FRESHNESS_MINUTES.

        Args:
            file_name: Name of the CSV file to check/generate
            generate_function: Function to call to generate the file
            freshness_minutes: Optional override for cache freshness threshold

        Returns:
            bool: True if file exists and is fresh or was generated successfully
        """
        logging.debug(
            "ENTRY: CacheUtils.check_and_generate_csv(file_name=%s, generate_function=%s, freshness_minutes=%s)",
            file_name,
            generate_function.__name__,
            freshness_minutes,
        )

        if freshness_minutes is None:
            freshness_minutes = CSV_FRESHNESS_MINUTES

        # Get the full path to the CSV file in the data directory
        full_file_path = FilePathUtils.get_csv_path(file_name)

        # Check if the file already exists
        if os.path.exists(full_file_path):
            try:
                # Get the last modified time of the file
                file_mtime = datetime.fromtimestamp(os.path.getmtime(full_file_path))
                logging.debug("File I/O: Successfully read modification time for %s: %s", full_file_path, file_mtime)

                # Check if the file is still fresh
                if datetime.now() - file_mtime < timedelta(minutes=freshness_minutes):
                    # Log that the cached file is being used
                    logging.info("! Using cached %s (fresh)", file_name)
                    logging.debug("EXIT: check_and_generate_csv - using cached file")
                    return True
                else:
                    # Log that the file is stale and will be regenerated
                    logging.info("* %s is older than %s minutes. Regenerating...", file_name, freshness_minutes)
            except OSError as error:
                logging.error("File I/O: Failed to read modification time for %s: %s", full_file_path, error)
                logging.info("* %s exists but cannot read metadata. Regenerating...", file_name)
        else:
            # Log that the file does not exist and will be generated
            logging.info("* %s not found. Generating...", file_name)

        # Call the function to generate the file
        logging.info("* Running %s to generate %s...", generate_function.__name__, file_name)
        try:
            generate_function()
            logging.info("! %s generated or refreshed.", file_name)
            logging.debug("EXIT: check_and_generate_csv - file generated successfully")
            return True
        except Exception as error:
            logging.error("Failed to generate %s using %s: %s", file_name, generate_function.__name__, error)
            logging.debug("EXIT: check_and_generate_csv - generation failed")
            return False

    @staticmethod
    def load_csv_grouped_by_key(filename: str, key: str) -> dict[str, list[dict[str, Any]]]:
        """
        Loads CSV data into a dictionary keyed by the specified column.
        Each key maps to a list of rows (as dictionaries) that share the same key value.

        Args:
            filename: Name of the CSV file to load
            key: Column name to use as the grouping key

        Returns:
            dict: Dictionary where keys are unique values from the key column,
                  and values are lists of row dictionaries
        """
        logging.info(
            "Loading CSV file '%s' into dictionary keyed by '%s'...", filename, key
        )  # Log before reading the file
        csv_file_path = FilePathUtils.get_csv_path(filename)  # Resolve the CSV path under the data/ directory
        with open(csv_file_path, encoding="utf-8") as file:  # Open the CSV for reading
            reader = csv.DictReader(file)  # Parse each row into a dictionary keyed by column name
            data_dict: dict[str, list[dict[str, Any]]] = {}  # Group rows by the chosen key column
            row_count = 0  # Count how many valid rows we ingest
            for row in reader:  # Process each CSV row
                data_key = row.get(key)  # Extract the grouping key value from this row
                if data_key is None:  # The key column is missing on this row
                    logging.warning("Row missing key '%s': %s", key, row)  # Warn about the malformed row
                    continue  # Skip rows that can't be grouped
                if data_key not in data_dict:  # First time we've seen this key value
                    data_dict[data_key] = []  # Start a new bucket for it
                data_dict[data_key].append(row)  # Add this row to its key's bucket
                row_count += 1  # Tally the ingested row
            logging.info(
                "Loaded %s rows from '%s'. Found %s unique keys for '%s'.", row_count, filename, len(data_dict), key
            )  # Summary log
        return data_dict  # Return the grouped-by-key dictionary

    @staticmethod
    def write_support_data_to_csv(data: dict[str, list[dict[str, Any]]], filename: str) -> None:
        """
        Writes the support package data (a dict of lists of dicts) to a CSV file.
        Each section in 'data' is a list of dictionaries. All unique keys across all sections are used as CSV columns.

        Args:
            data: Dictionary where keys are section names and values are lists of row dictionaries
            filename: Name of the output CSV file
        """
        logging.debug("Preparing to write support package to %s...", filename)

        fieldnames: set = set()  # type: ignore[type-arg]
        # Collect all unique field names from all sections
        for section_name, section in data.items():
            logging.debug("Processing section '%s' with %s rows.", section_name, len(section))
            for row in section:
                fieldnames.update(row.keys())
        fieldnames_sorted = sorted(fieldnames)

        logging.debug("Final CSV fieldnames: %s", fieldnames_sorted)

        # SECURITY: Use proper file path handling to ensure files go to data/ directory
        csv_file_path = FilePathUtils.get_csv_path(filename)
        with open(csv_file_path, mode="w", newline="", encoding="utf-8") as file:
            writer = csv.DictWriter(file, fieldnames=fieldnames_sorted)
            writer.writeheader()
            row_count = 0
            for _section_name, section in data.items():
                for row in section:
                    writer.writerow(row)
                    row_count += 1
            logging.info("Wrote %s rows to %s for support package.", row_count, csv_file_path)

        logging.info("Support package written to %s", csv_file_path)

    # Known generated cache CSV filenames -- cleared by Menu 175
    GENERATED_FILES: set[str] = {  # Explicit list of MistHelper-generated cache CSVs to protect non-data files
        "AllDevicesWithSiteInfo.csv",
        "GatewayDeviceStats.csv",
        "GatewayDeviceStatsWithSiteInfo.csv",
        "GatewayMgmtIPs.csv",
        "OrgDeviceEvents.csv",
        "OrgInventory.csv",
        "OrgSwitchVCStats.csv",
        "PortStats.csv",
        "SiteList.csv",
        "SitePortStats.csv",
        "VPNPeerStats.csv",
    }

    # Generated CSV filename prefixes -- any file in data/ matching these is a cache candidate
    GENERATED_PREFIXES: tuple[str, ...] = (  # Prefixes that identify auto-generated cache files
        "AllDevices",
        "AuditLogs",
        "DeviceEvents",
        "DevicePort",
        "Gateway",
        "Org",
        "Port",
        "Site",
        "Switch",
        "VPN",
    )

    @staticmethod
    def _is_generated_file(filename: str) -> bool:  # Check if file is MistHelper-generated
        """Return True if the filename matches a known generated cache file."""
        name = os.path.basename(filename)  # Strip any path component for clean matching
        if name in CacheUtils.GENERATED_FILES:  # Exact match against the explicit allowlist
            return True  # Explicitly listed -- safe to delete
        if name.endswith(".csv") and name.startswith(CacheUtils.GENERATED_PREFIXES):  # Prefix match
            return True  # Prefix match -- safe to delete
        return False  # Not a recognised generated file -- leave it alone

    @staticmethod
    def clear_cache() -> None:  # Menu 175: delete all generated cache CSVs from data/ directory
        """Delete all MistHelper-generated cache CSV files from the data/ directory."""
        data_dir = "data"  # Use relative path to data/ directory consistent with FilePathUtils.get_csv_path()
        logging.info("Scanning data directory for generated cache CSVs: %s", data_dir)  # Log scan target
        try:
            candidates = [  # List only safe-to-delete files
                f for f in os.listdir(data_dir) if CacheUtils._is_generated_file(f)
            ]
        except OSError as scan_error:  # Handle permission or missing directory errors gracefully
            logging.error("Failed to list data directory %s: %s", data_dir, scan_error)  # Log I/O failure with context
            print(f"! Error scanning data directory: {scan_error}")  # Surface error to operator
            return  # Abort -- nothing to delete if we can't list the directory
        if not candidates:  # Nothing to delete -- inform operator and return early
            print("! No generated cache CSV files found to delete.")  # User-friendly empty state message
            logging.info("No generated cache CSVs found in %s", data_dir)  # Log empty result
            return  # Early return -- nothing to do
        print(f"Found {len(candidates)} generated cache CSV file(s) to delete:")  # Show operator what will be removed
        for name in sorted(candidates):  # Sort for readable output
            print(f"  {name}")  # List each file so operator knows exactly what is affected
        deleted = 0  # Track successful deletions for summary
        errors = 0  # Track failures for summary
        for name in candidates:  # Delete each identified cache file
            full_path = os.path.join(data_dir, name)  # Build absolute path for deletion
            logging.info("Deleting cache CSV: %s", full_path)  # Log before deletion for audit trail
            try:
                os.remove(full_path)  # Delete the file from disk
                logging.debug("Deleted: %s", full_path)  # Confirm deletion at debug level
                deleted += 1  # Increment success counter
            except OSError as delete_error:  # Handle individual file deletion failures without aborting the batch
                logging.error("Failed to delete %s: %s", full_path, delete_error)  # Log failure with path and reason
                print(f"  ! Could not delete {name}: {delete_error}")  # Surface individual failure to operator
                errors += 1  # Increment error counter
        print(f"! Cache cleared: {deleted} file(s) deleted, {errors} error(s).")  # Summary line for operator
        logging.info("Cache clear complete: %d deleted, %d errors", deleted, errors)  # Log summary for post-run review

    @staticmethod
    def create_address_parse_failures_csv(
        parse_failures: list[dict[str, Any]], filename: str = "AddressParseFailures.csv"
    ) -> None:
        """
        Create a CSV file documenting address parsing failures.

        Args:
            parse_failures: List of parse failure records
            filename: Output filename
        """
        if not parse_failures:
            logging.info("No address parsing failures to document.")
            return

        try:
            output_path = FilePathUtils.get_csv_path(filename)

            with open(output_path, "w", newline="", encoding="utf-8") as f:
                fieldnames = [
                    "site_id",
                    "site_name",
                    "device_id",
                    "device_serial",
                    "device_name",
                    "original_address",
                    "parsed_tokens",
                    "failure_reason",
                    "timestamp",
                ]

                writer = csv.DictWriter(f, fieldnames=fieldnames)
                writer.writeheader()

                for failure in parse_failures:
                    writer.writerow(failure)

            logging.info("Address parsing failures documented in: %s (%s records)", filename, len(parse_failures))
            print(f"! Address parsing failures documented in: {filename} ({len(parse_failures)} records)")

        except Exception as e:
            logging.error("Failed to create address parse failures CSV: %s", e)
            print(f"! Failed to create address parse failures CSV: {e}")

    @staticmethod
    def fast_cache_hit(filename: str, max_age_minutes: int = 60) -> bool:  # Check if cached output file is fresh
        """Return True if the file exists in data/ and was written within max_age_minutes.

        Used as a lightweight guard to skip expensive re-generation when a fresh
        output already exists (e.g. a Markdown report generated earlier in the session).

        Args:
            filename: Filename to check inside the data/ directory
            max_age_minutes: How old the file can be before it is considered stale

        Returns:
            bool: True if file exists and is fresh (skip re-generation), False otherwise
        """
        full_path = FilePathUtils.get_csv_path(filename)  # Resolve path inside data/ directory
        logging.debug("fast_cache_hit check for %s (max_age=%d min)", filename, max_age_minutes)  # Log check
        if not os.path.exists(full_path):  # File not present -- always a miss
            logging.debug("fast_cache_hit MISS: %s not found", filename)  # Log miss reason
            return False  # Cache miss -- caller should generate the file
        try:
            age_seconds = time.time() - os.path.getmtime(full_path)  # Seconds since last modification
            age_minutes = age_seconds / 60.0  # Convert to minutes for readable comparison
            if age_minutes <= max_age_minutes:  # File is within the freshness window
                logging.info("fast_cache_hit HIT: %s (%.1f min old)", filename, age_minutes)  # Log cache hit
                print(  # Inform user that cached output is being reused
                    f"! Using cached {filename} ({age_minutes:.0f} min old) -- skipping re-generation."
                )
                return True  # Cache hit -- caller can skip expensive work
            logging.debug("fast_cache_hit MISS: %s is stale (%.1f min old)", filename, age_minutes)  # Log stale
            return False  # File is too old -- cache miss
        except OSError as stat_error:  # Handle race conditions or permission issues
            logging.warning("fast_cache_hit: could not stat %s: %s", filename, stat_error)  # Log I/O issue
            return False  # Treat stat failure as a miss to be safe


# ============================================================================
# DISPLAY UTILITIES CLASS
# ============================================================================
class DisplayUtils:
    """
    Centralized display and output utilities.
    Handles table formatting, pretty printing, etc.
    """

    @staticmethod
    def dict_list_as_pretty_table(
        data: list[dict[str, Any]], fields: list[str] | None = None, sortby: str | None = None
    ) -> None:
        """
        Displays a PrettyTable from a list of dictionaries.

        Args:
            data: List of dictionaries to display
            fields: Optional list of field names to display
            sortby: Optional field name to sort by
        """
        # Return early if there's no data to display
        if not data:
            return

        # Use provided fields or extract all unique keys
        fields = fields or DataProcessingUtils.get_unique_keys(data)  # type: ignore[no-untyped-call]

        # Initialize the PrettyTable with field names
        table = PrettyTable()
        table.field_names = fields

        # Set the sort column if it's valid
        if sortby and sortby in fields:
            table.sortby = sortby

        # Add each row of data to the table
        for item in data:
            row = [item.get(field, "") for field in fields]
            table.add_row(row)

        # Log the table as a string (debug mode only)
        logging.debug("\n%s", table.get_string())

    @staticmethod
    def create_progress_bar(progress_percentage: float | None, bar_length: int = 20) -> str:
        """
        Create an ASCII progress bar visualization for upgrade progress.

        Args:
            progress_percentage: Progress value from 0 to 100 (int or float)
            bar_length: Total length of the progress bar in characters

        Returns:
            str: Formatted progress bar string like "[=========>          ] 45%"
        """
        if progress_percentage is None or progress_percentage < 0:
            progress_percentage = 0
        elif progress_percentage > 100:
            progress_percentage = 100

        filled_length = int(bar_length * progress_percentage / 100)

        if filled_length == bar_length:
            # Complete: all filled
            bar = "=" * bar_length
        elif filled_length == 0:
            # Just started: all empty
            bar = " " * bar_length
        else:
            # In progress: filled portion + arrow + empty portion
            bar = "=" * (filled_length - 1) + ">" + " " * (bar_length - filled_length)

        return f"[{bar}] {progress_percentage:3d}%"


class DeviceDataFetcher:
    """
    Interactive device data fetcher for single-device operations.

    Fetches data for a specific device (by site_id/device_id or via user prompt),
    writes the result to CSV, and displays as PrettyTable.

    SECURITY: Uses authenticated API session for all device queries.

    Usage:
        DeviceDataFetcher(fetch_function, filename, description).fetch()
        DeviceDataFetcher(fetch_function, filename, description, device_type="gateway").fetch()
    """

    def __init__(  # noqa: PLR0913
        self,
        fetch_function: Callable,  # type: ignore[type-arg]
        filename: str,
        description: str,
        device_type: str = "all",
        site_id: str | None = None,
        device_id: str | None = None,
    ):
        """Initialize fetcher with required parameters."""
        self.fetch_function = fetch_function
        self.filename = filename
        self.description = description
        self.device_type = device_type
        self.site_id = site_id
        self.device_id = device_id

    @classmethod
    def from_config(cls, config: "DeviceFetchConfig") -> "DeviceDataFetcher":
        """Create fetcher from DeviceFetchConfig object."""
        return cls(
            fetch_function=config.fetch_function,
            filename=config.filename,
            description=config.description,
            device_type=config.device_type,
            site_id=config.site_id,
            device_id=config.device_id,
        )

    def fetch(self) -> None:
        """Main entry point - orchestrates the device data fetch workflow."""
        if not self._resolve_site_id():
            return
        if not self._resolve_device_id():
            return
        self._log_action()
        data = self._fetch_data()
        if data:
            self._process_and_output(data)

    def _resolve_site_id(self) -> bool:
        """Resolve site ID from parameter or user prompt."""
        if self.site_id:
            return True
        self.site_id = PromptUtils.select_site_id_from_csv()
        return bool(self.site_id)

    def _resolve_device_id(self) -> bool:
        """Resolve device ID from parameter or user prompt."""
        if self.device_id:
            return True
        assert self.site_id is not None, "Site ID must be resolved before device ID"  # nosec B101
        self.device_id = PromptUtils.select_device_id_from_inventory(self.site_id, device_type=self.device_type)
        return bool(self.device_id)

    def _log_action(self) -> None:
        """Log the action being performed."""
        logging.info("%s for device ID: %s", self.description, self.device_id)

    def _fetch_data(self) -> list[dict[str, Any]] | None:
        """Fetch data using the configured API function."""
        try:
            response = self.fetch_function(apisession, self.site_id, self.device_id)
            return [response.data] if response.data else None
        except Exception as error:
            logging.error("Failed to fetch device data: %s", error)
            return None

    def _process_and_output(self, data: list[dict[str, Any]]) -> None:
        """Process fetched data and output to CSV and table."""
        processed = DataProcessingUtils.flatten_nested_fields(data)
        processed = DataProcessingUtils.escape_multiline(processed)  # type: ignore[no-untyped-call]
        DataExporter.write_with_format_selection(processed, self.filename)  # type: ignore[no-untyped-call]
        DisplayUtils.dict_list_as_pretty_table(processed)


# Issue #431: module-level alias `PacketCaptureManager = ExtractedPacketCaptureManager`
# was removed. The canonical name is now imported directly at module top.


class SFPTransceiverDataProcessor:
    """Process and correlate SFP / transceiver data with site & device context.

    RATIONALE:
        This logic was previously a standalone function (`process_and_merge_csv_for_sfp_address`).
        It is only invoked by menu option 77 and has no tight coupling with most runtime state.
        Encapsulating it in a class improves hierarchy and opens the door for future extensions
        (e.g., JSON export, filtering, unit tests) without growing the legacy global scope.

    SECURITY:
        Operates only on locally generated CSV artifacts inside the controlled `data/` directory.
        No external network or credential usage. Filenames are static and not user-injected.
    """

    OUTPUT_FILENAME = "MergedTransceiverData.csv"

    @staticmethod
    def merge_transceiver_data():  # noqa: C901, PLR0915
        """Generate a merged transceiver CSV linking port optics to site + device context.

        Steps:
            1. Ensure prerequisite CSVs exist (generate if missing):
               - OrgDevicePortStats.csv
               - AllDevicesWithSiteInfo.csv
            2. Load device/site context keyed by MAC.
            3. Filter port stats to rows containing a non-empty transceiver model.
            4. Write merged result to `MergedTransceiverData.csv` via DataExporter.
        """
        logging.debug("ENTRY: SFPTransceiverDataProcessor.merge_transceiver_data()")

        org_port_stats_path = FilePathUtils.get_csv_path("OrgDevicePortStats.csv")
        devices_with_site_info_path = FilePathUtils.get_csv_path("AllDevicesWithSiteInfo.csv")

        # Generate prerequisites if absent (idempotent behavior matches prior function)
        if not os.path.exists(org_port_stats_path):
            print("* OrgDevicePortStats.csv not found. Generating it now...")
            logging.info("OrgDevicePortStats.csv missing; invoking OrgDeviceStatsExporter.device_port_stats()")
            OrgDeviceStatsExporter.device_port_stats()

        if not os.path.exists(devices_with_site_info_path):
            print("* AllDevicesWithSiteInfo.csv not found. Generating it now...")
            logging.info("AllDevicesWithSiteInfo.csv missing; invoking OrgInventoryExporter.devices_with_site_info()")
            OrgInventoryExporter.devices_with_site_info()

        try:
            # Load context keyed by MAC
            logging.debug("File I/O: Reading %s", devices_with_site_info_path)
            with open(devices_with_site_info_path, encoding="utf-8") as file:
                reader = csv.DictReader(file)
                site_info = {
                    row["mac"]: {
                        "site_name": row.get("site_name", ""),
                        "site_address": row.get("site_address", ""),
                        "device_name": row.get("name", ""),
                    }
                    for row in reader
                }
            logging.info("Loaded %s device entries from %s", len(site_info), devices_with_site_info_path)

            merged_data = []
            total_rows = 0
            candidate_rows = 0  # rows having a non-empty transceiver model (may or may not map to a known device MAC)
            matched_rows = 0  # rows contributing to merged output
            unique_devices_with_transceivers: set[str] = set()

            logging.debug("File I/O: Reading %s", org_port_stats_path)
            with open(org_port_stats_path, encoding="utf-8") as file:
                reader = csv.DictReader(file)
                for row in reader:
                    total_rows += 1
                    mac = row.get("mac")
                    transceiver_model = row.get("xcvr_model", "").strip()

                    if transceiver_model:
                        candidate_rows += 1

                    if mac in site_info and transceiver_model:
                        matched_rows += 1
                        if mac is not None:  # Ensure mac is not None before adding to set
                            unique_devices_with_transceivers.add(mac)
                        merged_data.append(
                            {
                                "site_name": site_info[mac]["site_name"],
                                "site_address": site_info[mac]["site_address"],
                                "device_name": site_info[mac]["device_name"],
                                "port_id": row.get("port_id", ""),
                                "transceiver_part_number": row.get("xcvr_part_number", ""),
                                "transceiver_model": transceiver_model,
                                "transceiver_serial_number": row.get("xcvr_serial", ""),
                            }
                        )

            if matched_rows == 0:
                # Downgraded severity explanation lives here; DataExporter currently emits a WARNING when given 0 rows.
                logging.info(
                    "Processed port stats; no matching transceivers found. total_rows=%d candidate_rows=%d known_devices=%d. "  # noqa: E501
                    "This can be normal if the inventory currently has no optics populated.",
                    total_rows,
                    candidate_rows,
                    len(site_info),
                )
            else:
                logging.info(
                    "Processed port stats; %d ports with transceivers found (total_rows=%d candidate_rows=%d unique_devices=%d)",  # noqa: E501
                    matched_rows,
                    total_rows,
                    candidate_rows,
                    len(unique_devices_with_transceivers),
                )

            DataExporter.write_with_format_selection(merged_data, SFPTransceiverDataProcessor.OUTPUT_FILENAME)  # type: ignore[no-untyped-call]  # Write the merged rows to the output backend
            logging.info(
                "Wrote %s rows to %s", len(merged_data), SFPTransceiverDataProcessor.OUTPUT_FILENAME
            )  # Log the row count written
            print(
                f"! Merged data written to {SFPTransceiverDataProcessor.OUTPUT_FILENAME}"
            )  # Tell the user where the file landed
            logging.debug("EXIT: SFPTransceiverDataProcessor.merge_transceiver_data - success")  # Trace successful exit
        except FileNotFoundError as e:  # A required input CSV was missing
            logging.error("File I/O: Required CSV file not found: %s", e)  # Log which file was absent
            logging.debug(
                "EXIT: SFPTransceiverDataProcessor.merge_transceiver_data - file not found"
            )  # Trace the failure exit
            raise  # Re-raise so the caller knows the merge could not run
        except csv.Error as e:  # The CSV parser hit malformed data
            logging.error("File I/O: CSV processing error: %s", e)  # Log the parsing error
            logging.debug(
                "EXIT: SFPTransceiverDataProcessor.merge_transceiver_data - CSV error"
            )  # Trace the failure exit
            raise  # Re-raise so the caller can handle the bad input
        except Exception as e:  # Any other unexpected failure during the merge
            logging.error("File I/O: Unexpected error during transceiver merge: %s", e)  # Log the unexpected error
            logging.debug(
                "EXIT: SFPTransceiverDataProcessor.merge_transceiver_data - unexpected error"
            )  # Trace the failure exit
            raise  # Re-raise to surface the problem to the caller


class FilePathUtils:
    """
    Centralized file path utilities for consistent data directory handling.
    Ensures all CSV and data files are placed in the correct data directory.
    All methods are static to avoid unnecessary object instantiation.
    """

    @staticmethod
    def get_csv_path(filename: str) -> str:  # Resolve a CSV name to a path under data/.
        """
        Helper function to ensure consistent CSV file paths in the data directory.

        Args:
            filename (str): The CSV filename (with or without path)

        Returns:
            str: Full path to the CSV file in the data directory
        """
        # Ensure data directory exists
        data_dir = "data"  # All exports are confined to the data/ directory.
        os.makedirs(data_dir, exist_ok=True)  # Create data/ on first use; no error if it exists.

        # If filename already includes a path, use it as-is
        if os.path.dirname(filename):  # Caller supplied an explicit directory.
            return filename  # Respect caller-provided paths verbatim.

        # Otherwise, place it in the data directory
        return os.path.join(data_dir, filename)  # Join bare names under data/ portably.

    @staticmethod
    def create_csv_template(
        filename: str, headers: list[str] | None = None, sample_data: list[list[str]] | None = None
    ) -> str:  # Create an empty CSV placeholder with optional headers.
        """
        Creates a basic CSV file placeholder in the correct location.

        Args:
            filename (str): Name of the CSV file to create
            headers (list): List of header names (optional)
            sample_data (list): Optional list of sample data rows (optional)

        Returns:
            str: Full path to the created file
        """
        file_path = FilePathUtils.get_csv_path(filename)  # Normalize the destination under data/.

        try:
            # Just create an empty file in the correct location
            with open(file_path, "w", newline="", encoding="utf-8") as f:  # Truncate/create the file.
                if headers:  # Only write a header row when headers were provided.
                    writer = csv.writer(f)  # Wrap the handle in a CSV writer.
                    writer.writerow(headers)  # Emit the single header row.
                # Don't write sample data - user will add their own content

            logging.info("Created template file: %s", file_path)  # Record the created placeholder.
            return file_path  # Hand the path back to the caller.
        except Exception as error:  # Never leave a partial file without surfacing the cause.
            logging.error("Failed to create template file %s: %s", filename, error)  # Log the failure cause.
            raise  # Re-raise so callers can handle the failure.


# ============================================================================
# ENVIRONMENT UTILITIES CLASS
# ============================================================================
class EnvironmentUtils:  # Centralized runtime/container environment detection.
    """
    Centralized environment detection utilities.
    Handles container detection, runtime environment identification, etc.
    """

    # Constants for container detection
    TRUE_VALUES = {"1", "true", "yes", "on"}  # Strings treated as boolean-true in env vars.
    OVERRIDE_ENV_VARS = ("MISTHELPER_FORCE_CONTAINER_LOOP", "MISTHELPER_CONTAINER")  # Manual override switches.
    CONTAINER_ENV_VARS = (  # Well-known vars set by container runtimes.
        "CONTAINER",
        "DOCKER_CONTAINER",
        "PODMAN_CONTAINER",
        "KUBERNETES_SERVICE_HOST",
        "CONTAINERD_NAMESPACE",
    )
    CGROUP_INDICATORS = ("docker", "containerd", "podman", "lxc")  # Substrings that mark a container cgroup.

    @staticmethod
    def _check_override_env_vars() -> bool | None:  # Honor an explicit operator override first.
        """Check for explicit container override environment variables."""
        for explicit_var in EnvironmentUtils.OVERRIDE_ENV_VARS:  # Inspect each override switch.
            value = os.environ.get(explicit_var, "").strip().lower()  # Normalize the configured value.
            if value in EnvironmentUtils.TRUE_VALUES:  # Operator forced container mode on.
                logging.debug("Container detection: override via %s=%s", explicit_var, value)  # Trace the override.
                return True  # Short-circuit: treat as a container.
        return None  # No override set; defer to other detectors.

    @staticmethod
    def _check_dockerenv_file() -> bool:  # Detect Docker's /.dockerenv sentinel file.
        """Check for /.dockerenv sentinel file."""
        if os.path.exists("/.dockerenv"):  # Docker drops this file inside containers.
            logging.debug("Container detection: /.dockerenv present")  # Trace the positive signal.
            return True  # Sentinel present means containerized.
        return False  # Absent sentinel is inconclusive here.

    @staticmethod
    def _check_container_env_vars() -> bool:  # Detect container runtimes via env vars.
        """Check for well-known container environment variables."""
        for env_var in EnvironmentUtils.CONTAINER_ENV_VARS:  # Probe each known runtime variable.
            if os.environ.get(env_var):  # Any non-empty value signals a container.
                logging.debug("Container detection: environment variable %s present", env_var)  # Trace which one.
                return True  # Treat as containerized.
        return False  # None present; inconclusive here.

    @staticmethod
    def _check_cgroup_markers() -> bool:
        """Check cgroup file for container indicators."""
        try:
            with open("/proc/1/cgroup", encoding="utf-8", errors="ignore") as cgroup_file:
                cgroup_content = cgroup_file.read().lower()
                for indicator in EnvironmentUtils.CGROUP_INDICATORS:  # Scan cgroup text for each runtime marker.
                    if indicator in cgroup_content:  # Marker substring present in cgroup.
                        logging.debug("Container detection: cgroup indicator '%s' found", indicator)  # marker found.
                        return True  # Containerized: a marker was found.
        except (FileNotFoundError, PermissionError):  # No cgroup file or no access (host/non-Linux).
            pass  # Treat missing cgroup as not-containerized.
        return False  # No cgroup markers: not a container.

    @staticmethod
    def _check_runtime_user() -> bool:  # Detect the container's dedicated service user.
        """Check if running as the 'misthelper' user."""
        try:
            import pwd  # Unix only

            current_user_name = pwd.getpwuid(os.getuid()).pw_name  # type: ignore[attr-defined]
            if current_user_name == "misthelper":  # Image runs as the misthelper user.
                logging.debug("Container detection: running as user 'misthelper'")  # Trace the user-based signal.
                return True  # Running as misthelper means containerized.
        except Exception:  # nosec B110
            pass  # Ignore lookup failures on host systems.
        return False  # User signal absent: inconclusive.

    @staticmethod
    def _check_app_path_with_sshd() -> bool:  # Detect the /app + sshd image layout.
        """Check for canonical container path /app with sshd presence."""
        try:
            this_file_dir = os.path.abspath(os.path.dirname(__file__))  # Absolute directory of this module.
            if this_file_dir.startswith("/app") and os.path.exists("/app/MistHelper.py"):  # In the image path.
                if os.path.exists("/usr/sbin/sshd"):  # Image ships the SSH daemon.
                    logging.debug("Container detection: /app path with MistHelper.py and sshd present")  # image signal.
                    return True  # Layout matches the container image.
        except Exception:  # nosec B110
            pass  # Ignore path-probing errors on host.
        return False  # Layout not present: inconclusive.

    @staticmethod
    def is_running_in_container() -> bool:  # Public aggregate container check.
        """Determine if execution appears to be inside a container.

        Detection strategy is deliberately multi-factor and conservative. A positive
        result enables continuous interactive looping behavior. False negatives can
        cause the menu to exit after one operation.

        Order of checks (first positive returns immediately):
          1. Explicit override environment variables
          2. Standard /.dockerenv sentinel file
          3. Well-known container environment variables
          4. cgroup markers
          5. Runtime user name 'misthelper'
          6. /app path detection with sshd presence

        SECURITY: Only boolean enabling of loop behavior; no privileged actions.
        """
        try:
            # Check override first (explicit operator control)
            override_result = EnvironmentUtils._check_override_env_vars()  # Operator override wins first.
            if override_result is not None:  # Override explicitly set the answer.
                return override_result  # Honor the forced value.

            # Check standard indicators in order of reliability
            checks = [  # Ordered fallback detectors.
                EnvironmentUtils._check_dockerenv_file,
                EnvironmentUtils._check_container_env_vars,
                EnvironmentUtils._check_cgroup_markers,
                EnvironmentUtils._check_runtime_user,
                EnvironmentUtils._check_app_path_with_sshd,
            ]

            for check in checks:  # Run each detector in order.
                if check():  # First positive detector wins.
                    return True  # A detector confirmed container.

        except Exception as container_detection_error:  # Never let detection crash startup.
            logging.debug("Container detection failed with exception: %s", container_detection_error)  # log failure.

        logging.debug("Container detection: no container indicators found - running in direct mode")  # direct mode.
        return False  # Default: not containerized.

    @staticmethod
    def is_debug_mode() -> bool:  # Report whether debug logging is on.
        """
        Check if debug mode is enabled via command line arguments.
        Delegates to module-level is_debug_mode() for consistency.

        Returns:
            bool: True if --debug or -d flag is present in sys.argv
        """
        return is_debug_mode()  # type: ignore[no-any-return, no-untyped-call]


# ============================================================================
# VALIDATION UTILITIES CLASS
# ============================================================================
class ValidationUtils:  # Input validators for API identifiers.
    """
    Centralized validation utilities for input validation and sanitization.
    All validation functions should be static methods in this class.
    """

    @staticmethod
    def validate_site_id(site_id: str | None, function_name: str = "unknown") -> bool:  # Guard site_id before API use.
        """
        Validates that site_id is not None or empty before making API calls.

        Args:
            site_id: The site ID to validate
            function_name: Name of the calling function for logging

        Returns:
            bool: True if valid, False otherwise

        Raises:
            ValueError: If site_id is None or empty
        """
        if site_id is None:  # Reject a missing site_id.
            error_msg = f"! site_id is None in {function_name}. Cannot make API call."  # Build the failure message.
            logging.error(error_msg)  # Log before raising.
            raise ValueError(error_msg)  # Abort the call with context.

        if isinstance(site_id, str) and site_id.strip() == "":  # Reject empty/whitespace site_id.
            error_msg = f"! site_id is empty string in {function_name}. Cannot make API call."  # empty-string msg.
            logging.error(error_msg)  # Log before raising.
            raise ValueError(error_msg)  # Abort the call.

        return True  # site_id passed validation.

    @staticmethod
    def validate_device_id(device_id: str | None, function_name: str = "unknown") -> bool:  # Guard device_id.
        """
        Validates that device_id is not None or empty before making API calls.

        Args:
            device_id: The device ID to validate
            function_name: Name of the calling function for logging

        Returns:
            bool: True if valid, False otherwise

        Raises:
            ValueError: If device_id is None or empty
        """
        if device_id is None:  # Reject a missing device_id.
            error_msg = f"! device_id is None in {function_name}. Cannot make API call."  # Build the failure message.
            logging.error(error_msg)  # Log before raising.
            raise ValueError(error_msg)  # Abort the call with context.

        if isinstance(device_id, str) and device_id.strip() == "":  # Reject empty/whitespace device_id.
            error_msg = f"! device_id is empty string in {function_name}. Cannot make API call."  # empty-string msg.
            logging.error(error_msg)  # Log before raising.
            raise ValueError(error_msg)  # Abort the call.

        return True  # device_id passed validation.

    @staticmethod
    def validate_ping_target(target: str) -> bool:  # Validate a ping destination string.
        """
        Validate ping target hostname or IP address.

        Args:
            target: Target hostname or IP address

        Returns:
            bool: True if valid target, False otherwise
        """
        if not target or len(target.strip()) == 0:  # Reject empty targets.
            return False  # Invalid: no target given.

        target = target.strip()  # Normalize surrounding whitespace.

        # Check if it's a valid IP address
        try:
            ipaddress.ip_address(target)  # Parse as a literal IP.
            return True  # Valid IP target.
        except ValueError:  # Not an IP; try hostname.
            pass  # Fall through to hostname check.

        # Check if it's a valid hostname
        # Basic hostname validation: alphanumeric, dots, hyphens
        if re.match(r"^[a-zA-Z0-9.-]+$", target) and len(target) <= 253:  # Allow valid hostname charset/length.
            # Ensure it doesn't start or end with a dot or hyphen
            if not target.startswith((".", "-")) and not target.endswith((".", "-")):  # Reject edge dot/dash.
                return True  # Valid hostname target.

        return False  # Invalid ping target.


# ============================================================================
# CONFIGURATION UTILITIES CLASS
# ============================================================================
class ConfigUtils:  # Org id and run-control helpers.
    """
    Centralized configuration utilities.
    Handles org_id retrieval, credentials, and configuration management.
    """

    @staticmethod
    def get_cached_or_prompted_org_id() -> str:  # Resolve org_id from cache/env/.env/prompt.
        """
        Get organization ID from various sources in order of preference:
        1. Global variable
        2. Environment variable
        3. .env file
        4. Interactive prompt
        """
        global org_id  # Cache resolved id in the module global.
        # 1. Check global variable
        if org_id:  # Reuse an already-resolved id.
            logging.info("! Using org_id from global variable: %s", org_id)  # Trace the cached source.
            return org_id  # type: ignore[no-any-return]
        # 2. Check environment variable (set by dotenv or OS)
        org_id_env = os.environ.get("org_id") or os.environ.get("ORG_ID")  # Try environment variables next.
        if org_id_env:  # Environment provided the id.
            org_id = org_id_env  # Cache the env value.
            logging.info("! Loaded org_id from environment: %s", org_id)  # Trace the env source.
            return org_id  # Use the env id.
        # 3. Fallback: Try to load from .env manually (rarely needed)
        try:
            with open(".env") as env_file:  # Fall back to the .env file.
                for line in env_file:  # Scan each line for org_id.
                    if line.strip().startswith("org_id="):  # Match the org_id assignment.
                        org_id = line.strip().split("=", 1)[1].strip().strip('"')  # Extract and unquote the value.
            if org_id:  # A value was parsed.
                logging.info("! Loaded org_id from .env: %s", org_id)  # Trace the .env source.
                return org_id  # Use the .env id.
        except FileNotFoundError:  # No .env file present.
            logging.warning("! .env file not found.")  # Warn that .env is missing.
        # 4. Prompt if still not set
        logging.info("* No org_id found in .env or CLI. Prompting user...")  # Prompt the user as last resort.
        org_id_list = mistapi.cli.select_org(apisession)  # Interactive org selection.
        if not org_id_list:  # Selection returned nothing.
            logging.error("Failed to retrieve org list. Check your API token and authentication.")  # Log list failure.
            print("[ERROR] Unable to retrieve organizations. Your API token may be invalid or expired.")  # Token hint.
            print("[ERROR] Please update MIST_API_TOKEN in your .env file and try again.")  # Point to .env token.
            sys.exit(1)  # Abort: no org to proceed with.
        org_id = org_id_list[0]  # Use the first selected org.
        return org_id  # type: ignore[no-any-return]

    @staticmethod
    def check_stop_signal() -> bool:  # Check for the user stop sentinel.
        """Check for stop_loop.txt signal file and remove if found.

        Any long-running loop that iterates over sites or devices with API
        calls should call this once per iteration so the user can cancel
        gracefully by creating the stop file.

        Returns:
            True if the stop signal was detected (caller should break).
        """
        if os.path.exists("stop_loop.txt"):  # Sentinel file requests a stop.
            try:
                os.remove("stop_loop.txt")  # Consume the sentinel once.
            except OSError:  # Ignore removal races.
                pass  # Best-effort cleanup only.
            print(" Stop signal detected. Ending operation early.")  # Notify the user of early stop.
            logging.info("Stop signal (stop_loop.txt) detected - operation stopped by user.")  # Log user stop.
            return True  # Signal callers to stop.
        return False  # No stop requested.


