class MapsManagerLauncher:
    """
    Launch MapsManager from external maps_manager.py module.

    The external module contains the full interactive map viewer implementation
    (~7,500 lines) supporting standalone execution and MistHelper integration.

    SECURITY: Read-only map viewing with interactive Dash web server

    Usage:
        MapsManagerLauncher().launch()
    """

    def __init__(self):
        """Initialize launcher with module reference placeholder."""
        self.maps_manager = None
        self.org_id: str = ""

    def launch(self) -> None:
        """Main entry point - orchestrates module import and execution."""
        logging.info("Menu #142: Starting Maps Manager")
        if not self._import_module():
            return
        if not self._get_org_id():
            return
        self._run_interactive_menu()
        logging.info("Menu #142: Maps Manager session completed")

    def _import_module(self) -> bool:
        """Import MapsManager from external module with error handling."""
        try:
            from src.maps.maps_manager import MapsManager as ExternalMapsManager

            self._external_class = ExternalMapsManager
            return True
        except ImportError as error:
            self._handle_import_error(error)
            return False

    def _handle_import_error(self, error: ImportError) -> None:
        """Log and display import failure message."""
        logging.error("Failed to import MapsManager from src/maps/maps_manager.py: %s", error)
        print("\nERROR: Could not load Maps Manager module.")
        print("Ensure src/maps/maps_manager.py exists")

    def _get_org_id(self) -> bool:
        """Get organization ID from cache or prompt."""
        try:
            self.org_id = ConfigUtils.get_cached_or_prompted_org_id()
            return bool(self.org_id)
        except Exception as error:
            self._handle_fatal_error(error)
            return False

    def _run_interactive_menu(self) -> None:
        """Instantiate and run the Maps Manager interactive menu."""
        try:
            self.maps_manager = self._external_class(apisession, self.org_id)
            self.maps_manager.run_interactive_menu()
        except Exception as error:
            self._handle_fatal_error(error)

    def _handle_fatal_error(self, error: Exception) -> None:
        """Log and display fatal error message."""
        logging.error("Error running Maps Manager: %s", error, exc_info=True)
        print(f"\nERROR: {error}")


class TUILauncher:
    """
    Launch Terminal User Interface mode from interactive menu.

    Replicates the --tui CLI flag behavior but returns to menu instead of exiting.
    Provides an interactive, keyboard-driven API browser.

    SECURITY: Read-only browser mode with safe API exploration

    Usage:
        TUILauncher().launch()
    """

    def __init__(self):
        """Initialize TUI launcher with console handler tracking."""
        self.console_handlers: list = []  # type: ignore[type-arg]
        self.debug_mode: bool = False

    def launch(self) -> None:
        """Main entry point: launch TUI mode from menu."""
        logging.info("TUI_MODE: Starting Terminal User Interface mode from menu")
        self._print_welcome()

        if not self._ensure_api_session():
            return

        self._suppress_console_logging()

        try:
            self._run_tui()
        except KeyboardInterrupt:
            self._handle_keyboard_interrupt()
        except Exception as error:
            self._handle_fatal_error(error)
        finally:
            self._restore_console_logging()

        self._print_exit_message()

    def _print_welcome(self) -> None:
        """Print TUI activation messages."""
        print("\n>> Terminal User Interface mode activated")
        print(">> Use arrow keys to navigate, Enter to select, Q to quit")

    def _ensure_api_session(self) -> bool:
        """Initialize Mist API session if needed."""
        global apisession
        if apisession:
            return True

        print(">> Initializing Mist API session...")
        if not initialize_mist_session():  # type: ignore[no-untyped-call]
            print("[ERROR] Failed to initialize Mist API session")
            logging.error("TUI_MODE: Could not initialize API session")
            return False

        print(">> API session initialized successfully")
        return True

    def _suppress_console_logging(self) -> None:
        """Remove console handlers to prevent interference with Rich TUI."""
        root_logger = logging.getLogger()
        self.console_handlers = [
            h
            for h in root_logger.handlers
            if isinstance(h, logging.StreamHandler) and not isinstance(h, logging.FileHandler)
        ]
        for handler in self.console_handlers:
            root_logger.removeHandler(handler)
            logging.debug("TUI_MODE: Removed console handler to prevent interference with Rich TUI")

    def _get_debug_mode(self) -> bool:
        """Get debug mode from global args if available."""
        args_obj = globals().get("args", type("obj", (), {"debug": False})())
        return getattr(args_obj, "debug", False)

    def _run_tui(self) -> None:
        """Create and run the TUI instance."""
        global apisession
        self.debug_mode = self._get_debug_mode()

        from src.ui.tui import MistHelperTUI  # PLC0415: lazy import

        tui = MistHelperTUI(debug_mode=self.debug_mode)  # type: ignore[no-untyped-call]
        tui.apisession = apisession

        if self.debug_mode:
            logging.debug("TUI_MODE: Debug mode is ACTIVE - enhanced logging enabled")

        tui.run()  # type: ignore[no-untyped-call]

    def _handle_keyboard_interrupt(self) -> None:
        """Handle user Ctrl+C interruption."""
        logging.info("TUI_MODE: User interrupted with Ctrl+C")
        print("\n[EXIT] TUI mode stopped by user")

    def _handle_fatal_error(self, error: Exception) -> None:
        """Handle fatal TUI errors."""
        logging.error("TUI_MODE: Fatal error - %s", error, exc_info=True)
        print(f"\n[ERROR] TUI mode crashed: {error}")

    def _restore_console_logging(self) -> None:
        """Restore console handlers after TUI mode exits."""
        root_logger = logging.getLogger()
        for handler in self.console_handlers:
            root_logger.addHandler(handler)
        logging.debug("TUI_MODE: Restored console handler after TUI exit")

    def _print_exit_message(self) -> None:
        """Print exit messages and debug timestamp if enabled."""
        self.debug_mode = self._get_debug_mode()

        if self.debug_mode:
            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]
            logging.debug("TUI_DEBUG: [%s] TUI_MODE function completed - returning to caller", timestamp)

        logging.info("TUI_MODE: TUI mode completed successfully")
        print("\n>> Returned from TUI mode to main menu")


# ============================================================================
# TELEMETRY EMITTER CLASS
# ============================================================================
class TelemetryEmitter:
    """Append-only NDJSON event writer for test and progress telemetry.

    Writes one JSON object per line to the target file.  All writes are
    best-effort: an I/O failure is logged but never interrupts the
    primary operation (FR-008).

    Usage::

        with TelemetryEmitter("data/test_events.jsonl") as emitter:
            emitter.emit({"event_type": "test_pass", ...})
    """

    RETENTION_LIMIT = 10

    def __init__(self, file_path: str):
        self._path = file_path
        self._handle = None
        try:
            parent = os.path.dirname(file_path)
            if parent:
                os.makedirs(parent, exist_ok=True)
            self._handle = open(file_path, "a", encoding="utf-8")
        except OSError as exc:
            logging.warning("TelemetryEmitter: cannot open %s: %s", file_path, exc)

    # -- core write ----------------------------------------------------------

    def emit(self, event: dict) -> None:  # type: ignore[type-arg]
        """Write *event* as a single JSON line (best-effort)."""
        if self._handle is None:
            return
        try:
            self._handle.write(json.dumps(event, default=str) + "\n")
            self._handle.flush()
        except OSError as exc:
            logging.warning("TelemetryEmitter: write failed: %s", exc)

    def close(self) -> None:
        """Flush and close the underlying file handle."""
        if self._handle is not None:
            try:
                self._handle.close()
            except OSError:
                pass
            self._handle = None

    # -- context manager -----------------------------------------------------

    def __enter__(self) -> "TelemetryEmitter":
        return self

    def __exit__(self, exc_type: type[BaseException] | None, exc_val: BaseException | None, exc_tb: object) -> None:
        self.close()

    # -- test event helpers ---------------------------------------------------

    def emit_test_start(self, menu_option: str | int, operation_name: str, test_mode: str) -> None:
        """Emit a test_start event."""
        self.emit(
            {
                "event_type": "test_start",
                "timestamp": datetime.now(UTC).isoformat(),
                "menu_option": str(menu_option),
                "operation_name": operation_name,
                "test_mode": test_mode,
            }
        )

    def emit_test_pass(self, menu_option: str | int, operation_name: str, duration: float, test_mode: str) -> None:
        """Emit a test_pass event."""
        self.emit(
            {
                "event_type": "test_pass",
                "timestamp": datetime.now(UTC).isoformat(),
                "menu_option": str(menu_option),
                "status": "pass",
                "operation_name": operation_name,
                "duration_seconds": round(duration, 3),
                "test_mode": test_mode,
            }
        )

    def emit_test_fail(
        self, menu_option: str | int, operation_name: str, duration: float, error: Exception, test_mode: str
    ) -> None:
        """Emit a test_fail event."""
        self.emit(
            {
                "event_type": "test_fail",
                "timestamp": datetime.now(UTC).isoformat(),
                "menu_option": str(menu_option),
                "status": "fail",
                "operation_name": operation_name,
                "duration_seconds": round(duration, 3),
                "error_type": type(error).__name__,
                "error_message": str(error)[:500],
                "test_mode": test_mode,
            }
        )

    def emit_test_skip(
        self, menu_option: str | int, operation_name: str, reason: str, category: str, test_mode: str
    ) -> None:
        """Emit a test_skip event."""
        self.emit(
            {
                "event_type": "test_skip",
                "timestamp": datetime.now(UTC).isoformat(),
                "menu_option": str(menu_option),
                "status": "skip",
                "operation_name": operation_name,
                "duration_seconds": 0.0,
                "skip_reason": reason,
                "skip_category": category,
                "test_mode": test_mode,
            }
        )

    def emit_test_summary(
        self, total: int, passed: int, failed: int, skipped: int, elapsed: float, test_mode: str
    ) -> None:  # noqa: PLR0913
        """Emit a test_summary event."""
        overall = "pass" if failed == 0 else "fail"
        self.emit(
            {
                "event_type": "test_summary",
                "timestamp": datetime.now(UTC).isoformat(),
                "menu_option": "0",
                "status": overall,
                "total_operations": total,
                "pass_count": passed,
                "fail_count": failed,
                "skip_count": skipped,
                "total_elapsed_seconds": round(elapsed, 3),
                "test_mode": test_mode,
            }
        )

    # -- progress event helpers -----------------------------------------------

    def emit_progress_start(self, menu_option: str | int, operation_name: str, total_items: int) -> None:
        """Emit a progress_start event."""
        self.emit(
            {
                "event_type": "progress_start",
                "timestamp": datetime.now(UTC).isoformat(),
                "menu_option": str(menu_option),
                "operation_name": operation_name,
                "total_items": total_items,
            }
        )

    def emit_progress_tick(
        self, menu_option: str | int, operation_name: str, total: int, current: object, completed: int, remaining: int
    ) -> None:  # noqa: PLR0913
        """Emit a progress_tick event."""
        self.emit(
            {
                "event_type": "progress_tick",
                "timestamp": datetime.now(UTC).isoformat(),
                "menu_option": str(menu_option),
                "operation_name": operation_name,
                "total_items": total,
                "current_item": str(current),
                "items_completed": completed,
                "items_remaining": remaining,
            }
        )

    def emit_progress_complete(
        self,
        menu_option: str | int,
        operation_name: str,
        total: int,
        processed: int,
        was_stopped: bool,
        duration: float,
    ) -> None:  # noqa: PLR0913
        """Emit a progress_complete event."""
        self.emit(
            {
                "event_type": "progress_complete",
                "timestamp": datetime.now(UTC).isoformat(),
                "menu_option": str(menu_option),
                "operation_name": operation_name,
                "total_items": total,
                "items_processed": processed,
                "was_stopped": was_stopped,
                "duration_seconds": round(duration, 3),
            }
        )

    # -- retention ------------------------------------------------------------

    def enforce_retention(
        self, directory: str = "data", prefix: str = "test_events_", limit: int | None = None
    ) -> None:
        """Delete oldest timestamped JSONL files when count exceeds *limit*."""
        if limit is None:
            limit = self.RETENTION_LIMIT
        try:
            pattern = os.path.join(directory, f"{prefix}*.jsonl")
            import glob

            files = sorted(glob.glob(pattern))
            while len(files) > limit:
                oldest = files.pop(0)
                os.remove(oldest)
                logging.info("TelemetryEmitter: removed old file %s", oldest)
        except OSError as exc:
            logging.warning("TelemetryEmitter: retention cleanup failed: %s", exc)

    # -- timestamped filename helper -----------------------------------------

    @staticmethod
    def timestamped_path(directory: str = "data") -> str:
        """Return a timestamped JSONL path for a test run."""
        stamp = datetime.now(UTC).strftime("%Y%m%d_%H%M%S")
        return os.path.join(directory, f"test_events_{stamp}.jsonl")


